from scipy.optimize import least_squares
def model(th,t,P,kind):
    a0,a1,a2,b0,b1,b2,p,q=th
    if kind==0: T=t**p
    elif kind==1: T=np.exp(-p*t)
    elif kind==2: T=t**p*np.exp(-q*t)
    elif kind==3: T=np.log(1+p*t)
    return a0+a1*P+a2*P**2 + T*(b0+b1*P+b2*P**2)
